-- NEED 2026-10-13 의상 인챈트 스톤 세탁 악용 회수 (1/2 : 탐지)
--
-- 악용 경로
--   옷장 "입기"로 받은 귀속(bound) 의상을 말랑도 스톤 부여 NPC(에이버 드 도쉬 / 레이스 라 자드)에
--   넣으면 delequip 후 getitem2 로 재지급되면서 귀속이 풀린다. 이 비귀속 의상을 헤이담 펠로우에게
--   교환하면 원하는 의상 인챈트 스톤 상자를 무한히 받을 수 있었다. (수정: malangdo_costume.txt)
--
-- 탐지 기준 (picklog)
--   세탁 : map=lasa_in01, type N, 의상 귀속본 -1 직후(50행/5초 이내) 같은 캐릭터·같은 의상 비귀속본 +1
--   교환 : map=itemmall, type N, 비귀속 의상 -1 이 세탁본과 같은 unique_id (unique_id 가 0 이면 같은 캐릭터)
--   대상 : 세탁본을 헤이담에서 1회 이상 교환한 계정 (세탁만 한 계정은 참고 목록으로만 출력)
--
-- 이 파일은 게임 테이블을 바꾸지 않는다. 여러 번 실행해도 된다(INSERT IGNORE).
-- 결과를 검토한 뒤 봐줄 계정은 아래처럼 제외하고 2/2(적용)를 실행한다.
--   UPDATE `need_elr_target` SET `excluded` = 1, `note` = '사유' WHERE `account_id` = ?;

SET NAMES utf8mb4;

SET @since       := '2026-06-01 00:00:00';  -- 옷장 귀속 지급(2026-06-13) 이전부터
SET @enchant_map := 'lasa_in01';            -- 에이버 드 도쉬 / 레이스 라 자드
SET @heidam_map  := 'itemmall';             -- 헤이담 펠로우

-- ------------------------------------------------------------------
-- 기준표 : stone = 인챈트 스톤 재료, box = 의상 인챈트 스톤 상자, card = 슬롯에 박히는 인챈트,
--          costume = 의상 아이템(Locations: Costume_*)
-- 생성: npc/NEED/Costume.txt StoneData(EffectStoneData 제외) + malangdo_costume.txt 스톤 NPC 목록
--       + 헤이담 .@box_list + db/re/item_db_equip.yml·db/import/item_db.yml·need_summer_item_db.yml
-- ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `need_elr_item` (
  `item_id` int unsigned NOT NULL,
  `kind` enum('stone','box','card','costume') NOT NULL,
  PRIMARY KEY (`item_id`,`kind`),
  KEY `kind` (`kind`,`item_id`)
) ENGINE=InnoDB;

-- stone 362 / box 7 / card 354 / costume 3319

-- ------------------------------------------------------------------
-- 1) 세탁 이벤트
-- ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `need_elr_event` (
  `del_log_id` int unsigned NOT NULL COMMENT 'picklog id (귀속본 -1)',
  `add_log_id` int unsigned NOT NULL COMMENT 'picklog id (비귀속본 +1)',
  `char_id` int unsigned NOT NULL,
  `account_id` int unsigned NOT NULL DEFAULT 0,
  `nameid` int unsigned NOT NULL,
  `time` datetime NOT NULL,
  `bound_before` tinyint unsigned NOT NULL,
  `unique_id_after` bigint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`del_log_id`),
  KEY `uid` (`unique_id_after`),
  KEY `char_item` (`char_id`,`nameid`),
  KEY `account_id` (`account_id`)
) ENGINE=InnoDB;

SELECT a.id, MIN(b.id), a.char_id, a.nameid, a.time, a.bound
FROM `picklog` a
JOIN `need_elr_item` ci ON ci.item_id = a.nameid AND ci.kind = 'costume'
JOIN `picklog` b ON b.id BETWEEN a.id + 1 AND a.id + 50
                AND b.char_id = a.char_id AND b.nameid = a.nameid
                AND b.type = 'N' AND b.amount = 1 AND b.bound = 0 AND b.map = a.map
                AND b.time BETWEEN a.time AND a.time + INTERVAL 5 SECOND
WHERE a.type = 'N' AND a.amount = -1 AND a.bound > 0
  AND a.map = @enchant_map AND a.time >= @since
GROUP BY a.id, a.char_id, a.nameid, a.time, a.bound;

UPDATE `need_elr_event` e JOIN `picklog` b ON b.id = e.add_log_id
SET e.unique_id_after = b.unique_id;

UPDATE `need_elr_event` e JOIN `char` c ON c.char_id = e.char_id
SET e.account_id = c.account_id
WHERE e.account_id = 0;

-- ------------------------------------------------------------------
-- 2) 헤이담 교환 기록과 연결
-- ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `need_elr_heidam` (
  `log_id` int unsigned NOT NULL,
  `char_id` int unsigned NOT NULL,
  `account_id` int unsigned NOT NULL DEFAULT 0,
  `nameid` int unsigned NOT NULL,
  `unique_id` bigint unsigned NOT NULL DEFAULT 0,
  `time` datetime NOT NULL,
  PRIMARY KEY (`log_id`),
  KEY `uid` (`unique_id`),
  KEY `char_item` (`char_id`,`nameid`)
) ENGINE=InnoDB;

SELECT p.id, p.char_id, p.nameid, p.unique_id, p.time
FROM `picklog` p
JOIN `need_elr_item` ci ON ci.item_id = p.nameid AND ci.kind = 'costume'
WHERE p.type = 'N' AND p.amount = -1 AND p.bound = 0
  AND p.map = @heidam_map AND p.time >= @since;

UPDATE `need_elr_heidam` h JOIN `char` c ON c.char_id = h.char_id
SET h.account_id = c.account_id
WHERE h.account_id = 0;

CREATE TABLE IF NOT EXISTS `need_elr_link` (
  `del_log_id` int unsigned NOT NULL,
  `heidam_log_id` int unsigned NOT NULL,
  PRIMARY KEY (`del_log_id`,`heidam_log_id`),
  KEY `heidam_log_id` (`heidam_log_id`)
) ENGINE=InnoDB;

-- unique_id 로 추적 (거래로 다른 캐릭터에게 넘어간 뒤 교환한 경우도 잡힌다)
SELECT e.del_log_id, h.log_id
FROM `need_elr_event` e
JOIN `need_elr_heidam` h ON h.unique_id = e.unique_id_after AND h.nameid = e.nameid AND h.log_id > e.add_log_id
WHERE e.unique_id_after <> 0;

-- unique_id 가 없는 기록은 같은 캐릭터·같은 의상으로 추적
SELECT e.del_log_id, h.log_id
FROM `need_elr_event` e
JOIN `need_elr_heidam` h ON h.char_id = e.char_id AND h.nameid = e.nameid AND h.log_id > e.add_log_id
WHERE e.unique_id_after = 0;

-- ------------------------------------------------------------------
-- 3) 회수 대상 계정 (세탁본을 헤이담에서 1회 이상 교환)
-- ------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `need_elr_target` (
  `account_id` int unsigned NOT NULL,
  `launder_cnt` int unsigned NOT NULL DEFAULT 0 COMMENT '세탁 횟수',
  `exchange_cnt` int unsigned NOT NULL DEFAULT 0 COMMENT '세탁본 헤이담 교환 횟수(= 받은 상자 수)',
  `first_at` datetime DEFAULT NULL,
  `last_at` datetime DEFAULT NULL,
  `excluded` tinyint unsigned NOT NULL DEFAULT 0 COMMENT '1 = 회수 제외(운영 판단)',
  `status` tinyint unsigned NOT NULL DEFAULT 0 COMMENT '0=대기, 1=회수 완료',
  `removed_stone` int unsigned NOT NULL DEFAULT 0,
  `removed_box` int unsigned NOT NULL DEFAULT 0,
  `stripped_card` int unsigned NOT NULL DEFAULT 0 COMMENT '의상에서 지운 인챈트 슬롯 수',
  `removed_closet` int unsigned NOT NULL DEFAULT 0 COMMENT '지운 옷장 스톤 세팅 수',
  `applied_at` datetime DEFAULT NULL,
  `note` varchar(64) NOT NULL DEFAULT '',
  PRIMARY KEY (`account_id`),
  KEY `status` (`status`,`excluded`)
) ENGINE=InnoDB;

SELECT e.account_id, COUNT(DISTINCT e.del_log_id), COUNT(DISTINCT l.heidam_log_id), MIN(e.time), MAX(e.time)
FROM `need_elr_event` e
LEFT JOIN `need_elr_link` l ON l.del_log_id = e.del_log_id
WHERE e.account_id <> 0
GROUP BY e.account_id
HAVING COUNT(DISTINCT l.heidam_log_id) > 0
ON DUPLICATE KEY UPDATE
  `launder_cnt` = IF(`status` = 0, VALUES(`launder_cnt`), `launder_cnt`),
  `exchange_cnt` = IF(`status` = 0, VALUES(`exchange_cnt`), `exchange_cnt`),
  `first_at` = IF(`status` = 0, VALUES(`first_at`), `first_at`),
  `last_at` = IF(`status` = 0, VALUES(`last_at`), `last_at`);

-- ------------------------------------------------------------------
-- 4) 검토용 출력
-- ------------------------------------------------------------------
-- 4-1) 회수 대상 계정
SELECT t.account_id, lg.userid, t.launder_cnt AS `세탁`, t.exchange_cnt AS `교환(상자)`,
       t.first_at AS `최초`, t.last_at AS `최근`, t.excluded AS `제외`, t.status AS `상태`,
       (SELECT GROUP_CONCAT(c.name ORDER BY c.char_num SEPARATOR ', ') FROM `char` c WHERE c.account_id = t.account_id) AS `캐릭터`
FROM `need_elr_target` t
LEFT JOIN `login` lg ON lg.account_id = t.account_id
ORDER BY t.exchange_cnt DESC, t.account_id;

-- 4-2) 참고 : 세탁만 하고 헤이담 교환 기록이 없는 계정 (회수 대상 아님)
SELECT e.account_id, COUNT(*) AS `세탁`, MIN(e.time) AS `최초`, MAX(e.time) AS `최근`
FROM `need_elr_event` e
LEFT JOIN `need_elr_link` l ON l.del_log_id = e.del_log_id
WHERE l.del_log_id IS NULL
  AND e.account_id NOT IN (SELECT `account_id` FROM `need_elr_target`)
GROUP BY e.account_id
ORDER BY 2 DESC;

-- 4-3) 참고 : 세탁본을 다른 계정이 교환한 기록 (거래로 넘겨받은 계정. 회수 대상 아님)
SELECT h.account_id AS `교환한_계정`, e.account_id AS `세탁한_계정`, COUNT(*) AS `건수`
FROM `need_elr_link` l
JOIN `need_elr_event` e ON e.del_log_id = l.del_log_id
JOIN `need_elr_heidam` h ON h.log_id = l.heidam_log_id
WHERE h.account_id <> e.account_id
GROUP BY h.account_id, e.account_id
ORDER BY 3 DESC;

-- 4-4) 회수 예정량 (계정별. 2/2 적용 전 확인용)
SELECT t.account_id,
  (SELECT COALESCE(SUM(i.amount),0) FROM `inventory` i JOIN `char` c ON c.char_id = i.char_id
     JOIN `need_elr_item` k ON k.item_id = i.nameid AND k.kind = 'stone' WHERE c.account_id = t.account_id)
  + (SELECT COALESCE(SUM(i.amount),0) FROM `cart_inventory` i JOIN `char` c ON c.char_id = i.char_id
     JOIN `need_elr_item` k ON k.item_id = i.nameid AND k.kind = 'stone' WHERE c.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'stone' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage2` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'stone' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage3` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'stone' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(a.amount),0) FROM `mail_attachments` a JOIN `mail` m ON m.id = a.id JOIN `char` c ON c.char_id = m.dest_id
     JOIN `need_elr_item` k ON k.item_id = a.nameid AND k.kind = 'stone' WHERE c.account_id = t.account_id) AS `스톤`,
  (SELECT COALESCE(SUM(i.amount),0) FROM `inventory` i JOIN `char` c ON c.char_id = i.char_id
     JOIN `need_elr_item` k ON k.item_id = i.nameid AND k.kind = 'box' WHERE c.account_id = t.account_id)
  + (SELECT COALESCE(SUM(i.amount),0) FROM `cart_inventory` i JOIN `char` c ON c.char_id = i.char_id
     JOIN `need_elr_item` k ON k.item_id = i.nameid AND k.kind = 'box' WHERE c.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'box' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage2` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'box' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(s.amount),0) FROM `storage3` s
     JOIN `need_elr_item` k ON k.item_id = s.nameid AND k.kind = 'box' WHERE s.account_id = t.account_id)
  + (SELECT COALESCE(SUM(a.amount),0) FROM `mail_attachments` a JOIN `mail` m ON m.id = a.id JOIN `char` c ON c.char_id = m.dest_id
     JOIN `need_elr_item` k ON k.item_id = a.nameid AND k.kind = 'box' WHERE c.account_id = t.account_id) AS `상자`,
  (SELECT COUNT(*) FROM `char_reg_num` g JOIN `char` c ON c.char_id = g.char_id
     WHERE c.account_id = t.account_id AND g.`index` = 0 AND g.`value` <> 0
       AND g.`key` IN ('COSTUME_STONE_TOP','COSTUME_STONE_MID','COSTUME_STONE_LOW','COSTUME_STONE_GARMENT','COSTUME_STONE_DUAL')) AS `옷장_세팅`
FROM `need_elr_target` t
WHERE t.status = 0 AND t.excluded = 0
ORDER BY t.account_id;
